import './styles.css';
import { useState, useMemo } from 'react';

// Fruit data with features
interface Fruit {
  id: string;
  name: string;
  emoji: string;
  sweetness: number; // 1-10
  sourness: number; // 1-10
  color: string;
}

const allFruits: Fruit[] = [
  { id: 'apple', name: 'Apple', emoji: '🍎', sweetness: 7, sourness: 3, color: '#ef4444' },
  { id: 'lemon', name: 'Lemon', emoji: '🍋', sweetness: 2, sourness: 9, color: '#eab308' },
  { id: 'banana', name: 'Banana', emoji: '🍌', sweetness: 8, sourness: 1, color: '#fde047' },
  { id: 'orange', name: 'Orange', emoji: '🍊', sweetness: 6, sourness: 4, color: '#f97316' },
  { id: 'grape', name: 'Grape', emoji: '🍇', sweetness: 8, sourness: 2, color: '#8b5cf6' },
  { id: 'lime', name: 'Lime', emoji: '🫒', sweetness: 2, sourness: 8, color: '#22c55e' },
  { id: 'strawberry', name: 'Strawberry', emoji: '🍓', sweetness: 7, sourness: 3, color: '#ec4899' },
  { id: 'grapefruit', name: 'Grapefruit', emoji: '🍊', sweetness: 4, sourness: 6, color: '#fb923c' },
];

// Training fruits (user will label these)
const trainingFruits = allFruits.slice(0, 5);
// Test fruits (model will predict these)
const testFruits = allFruits.slice(5);

type Label = 'sweet' | 'sour' | null;

// Simple "model" that learns from labeled examples
function predictLabel(fruit: Fruit, labels: Record<string, Label>): { prediction: Label; confidence: number } {
  const labeledFruits = trainingFruits.filter(f => labels[f.id] !== null);

  if (labeledFruits.length === 0) {
    return { prediction: null, confidence: 0 };
  }

  // Calculate average sweetness/sourness for each category
  const sweetFruits = labeledFruits.filter(f => labels[f.id] === 'sweet');
  const sourFruits = labeledFruits.filter(f => labels[f.id] === 'sour');

  if (sweetFruits.length === 0 || sourFruits.length === 0) {
    // Not enough data to make a good prediction
    return { prediction: sweetFruits.length > 0 ? 'sweet' : 'sour', confidence: 0.5 };
  }

  // Simple distance-based prediction
  const avgSweetSweet = sweetFruits.reduce((sum, f) => sum + f.sweetness, 0) / sweetFruits.length;
  const avgSourSweet = sweetFruits.reduce((sum, f) => sum + f.sourness, 0) / sweetFruits.length;
  const avgSweetSour = sourFruits.reduce((sum, f) => sum + f.sweetness, 0) / sourFruits.length;
  const avgSourSour = sourFruits.reduce((sum, f) => sum + f.sourness, 0) / sourFruits.length;

  // Distance to sweet category center
  const distSweet = Math.sqrt(
    Math.pow(fruit.sweetness - avgSweetSweet, 2) + 
    Math.pow(fruit.sourness - avgSourSweet, 2)
  );

  // Distance to sour category center
  const distSour = Math.sqrt(
    Math.pow(fruit.sweetness - avgSweetSour, 2) + 
    Math.pow(fruit.sourness - avgSourSour, 2)
  );

  const prediction: Label = distSweet < distSour ? 'sweet' : 'sour';
  const totalDist = distSweet + distSour;
  const confidence = totalDist > 0 ? Math.abs(distSour - distSweet) / totalDist : 0.5;

  return { prediction, confidence: 0.5 + confidence * 0.5 };
}

function FruitCard({ 
  fruit, 
  label, 
  onLabel, 
  showFeatures,
  disabled 
}: { 
  fruit: Fruit; 
  label: Label; 
  onLabel?: (label: Label) => void;
  showFeatures?: boolean;
  disabled?: boolean;
}) {
  return (
    <div className={`fruit-card ${label ? `labeled-${label}` : ''} ${disabled ? 'disabled' : ''}`}>
      <div className="fruit-emoji">{fruit.emoji}</div>
      <div className="fruit-name">{fruit.name}</div>

      {showFeatures && (
        <div className="fruit-features">
          <div className="feature">
            <span className="feature-label">Sweetness</span>
            <div className="feature-bar">
              <div className="feature-fill sweet" style={{ width: `${fruit.sweetness * 10}%` }} />
            </div>
          </div>
          <div className="feature">
            <span className="feature-label">Sourness</span>
            <div className="feature-bar">
              <div className="feature-fill sour" style={{ width: `${fruit.sourness * 10}%` }} />
            </div>
          </div>
        </div>
      )}

      {onLabel && !disabled && (
        <div className="label-buttons">
          <button 
            className={`label-btn sweet ${label === 'sweet' ? 'selected' : ''}`}
            onClick={() => onLabel(label === 'sweet' ? null : 'sweet')}
          >
            Sweet
          </button>
          <button 
            className={`label-btn sour ${label === 'sour' ? 'selected' : ''}`}
            onClick={() => onLabel(label === 'sour' ? null : 'sour')}
          >
            Sour
          </button>
        </div>
      )}

      {label && disabled && (
        <div className={`prediction-badge ${label}`}>
          {label === 'sweet' ? 'Sweet' : 'Sour'}
        </div>
      )}
    </div>
  );
}

function PredictionCard({ 
  fruit, 
  prediction,
  confidence,
  revealed,
  onReveal
}: { 
  fruit: Fruit; 
  prediction: Label;
  confidence: number;
  revealed: boolean;
  onReveal: () => void;
}) {
  const actualLabel: Label = fruit.sweetness > fruit.sourness ? 'sweet' : 'sour';
  const isCorrect = prediction === actualLabel;

  return (
    <div className={`fruit-card prediction-card ${revealed ? (isCorrect ? 'correct' : 'incorrect') : ''}`}>
      <div className="fruit-emoji">{fruit.emoji}</div>
      <div className="fruit-name">{fruit.name}</div>

      {!revealed ? (
        <>
          {prediction ? (
            <div className="prediction-info">
              <div className={`model-prediction ${prediction}`}>
                Model predicts: <strong>{prediction}</strong>
              </div>
              <div className="confidence">
                Confidence: {Math.round(confidence * 100)}%
              </div>
              <button className="reveal-btn" onClick={onReveal}>
                Check Answer
              </button>
            </div>
          ) : (
            <div className="no-prediction">
              Need more training data!
            </div>
          )}
        </>
      ) : (
        <div className="result-info">
          <div className={`result-badge ${isCorrect ? 'correct' : 'incorrect'}`}>
            {isCorrect ? 'Correct!' : 'Wrong!'}
          </div>
          <div className="actual-label">
            Actually: <strong>{actualLabel}</strong>
          </div>
        </div>
      )}
    </div>
  );
}

export default function App() {
  const [labels, setLabels] = useState<Record<string, Label>>({});
  const [revealed, setRevealed] = useState<Record<string, boolean>>({});
  const [showFeatures, setShowFeatures] = useState(false);

  const labeledCount = Object.values(labels).filter(l => l !== null).length;

  const predictions = useMemo(() => {
    const result: Record<string, { prediction: Label; confidence: number }> = {};
    testFruits.forEach(fruit => {
      result[fruit.id] = predictLabel(fruit, labels);
    });
    return result;
  }, [labels]);

  const handleLabel = (fruitId: string, label: Label) => {
    setLabels(prev => ({ ...prev, [fruitId]: label }));
    // Reset predictions when labels change
    setRevealed({});
  };

  const handleReveal = (fruitId: string) => {
    setRevealed(prev => ({ ...prev, [fruitId]: true }));
  };

  const handleReset = () => {
    setLabels({});
    setRevealed({});
  };

  const correctCount = testFruits.filter(f => {
    if (!revealed[f.id]) return false;
    const actualLabel: Label = f.sweetness > f.sourness ? 'sweet' : 'sour';
    return predictions[f.id].prediction === actualLabel;
  }).length;

  const revealedCount = Object.values(revealed).filter(Boolean).length;

  return (
    <div className="app">
      <div className="header">
        <h1>Teach the Machine</h1>
        <p className="subtitle">
          Experience supervised learning! Label the training fruits, then watch the model predict new ones.
        </p>
      </div>

      <div className="controls">
        <label className="toggle-label">
          <input 
            type="checkbox" 
            checked={showFeatures} 
            onChange={(e) => setShowFeatures(e.target.checked)} 
          />
          Show fruit features (the data the model sees)
        </label>
        <button className="reset-btn" onClick={handleReset}>
          Reset All
        </button>
      </div>

      <div className="section training-section">
        <div className="section-header">
          <h2>Step 1: Label Training Data</h2>
          <span className="progress-badge">{labeledCount}/5 labeled</span>
        </div>
        <p className="section-desc">
          Click "Sweet" or "Sour" to teach the model what each fruit is. The model learns from YOUR labels!
        </p>
        <div className="fruit-grid">
          {trainingFruits.map(fruit => (
            <FruitCard
              key={fruit.id}
              fruit={fruit}
              label={labels[fruit.id] || null}
              onLabel={(label) => handleLabel(fruit.id, label)}
              showFeatures={showFeatures}
            />
          ))}
        </div>
      </div>

      <div className="section prediction-section">
        <div className="section-header">
          <h2>Step 2: Test the Model</h2>
          {revealedCount > 0 && (
            <span className="score-badge">
              {correctCount}/{revealedCount} correct
            </span>
          )}
        </div>
        <p className="section-desc">
          Based on what it learned, the model predicts labels for fruits it's never seen. Check if it's right!
        </p>
        <div className="fruit-grid">
          {testFruits.map(fruit => (
            <PredictionCard
              key={fruit.id}
              fruit={fruit}
              prediction={predictions[fruit.id].prediction}
              confidence={predictions[fruit.id].confidence}
              revealed={revealed[fruit.id] || false}
              onReveal={() => handleReveal(fruit.id)}
            />
          ))}
        </div>
      </div>

      <div className="insight-box">
        <h3>What's Happening Behind the Scenes?</h3>
        <p>
          The model looks at the <strong>sweetness</strong> and <strong>sourness</strong> values of fruits you labeled.
          It calculates the "center" of sweet fruits and sour fruits, then predicts new fruits based on
          which center they're closer to.
        </p>
        <p>
          <strong>Try it:</strong> Label all fruits as "sweet" and watch the predictions change!
          The model can only learn from the examples you give it.
        </p>
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
