  background: linear-gradient(135deg, #0ea5e9 0%, #6366f1 100%);
  min-height: 100vh;
  padding: 2rem 1rem;
}

.app {
  max-width: 900px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 2rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.9);
  font-size: 1rem;
}

.controls {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: rgba(255, 255, 255, 0.1);
  padding: 0.75rem 1rem;
  border-radius: 0.75rem;
  margin-bottom: 1.5rem;
}

.toggle-label {
  color: white;
  font-size: 0.875rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  cursor: pointer;
}

.reset-btn {
  background: rgba(255, 255, 255, 0.2);
  color: white;
  border: none;
  padding: 0.5rem 1rem;
  border-radius: 0.5rem;
  cursor: pointer;
  font-size: 0.875rem;
  transition: background 0.2s;
}

.reset-btn:hover {
  background: rgba(255, 255, 255, 0.3);
}

.section {
  background: white;
  border-radius: 1rem;
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.5rem;
}

.section h2 {
  color: #1f2937;
  font-size: 1.25rem;
}

.section-desc {
  color: #6b7280;
  font-size: 0.9rem;
  margin-bottom: 1rem;
}

.progress-badge, .score-badge {
  background: #dbeafe;
  color: #1d4ed8;
  padding: 0.25rem 0.75rem;
  border-radius: 1rem;
  font-size: 0.8rem;
  font-weight: 600;
}

.score-badge {
  background: #d1fae5;
  color: #065f46;
}

.fruit-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 1rem;
}

.fruit-card {
  background: #f9fafb;
  border: 2px solid #e5e7eb;
  border-radius: 1rem;
  padding: 1rem;
  text-align: center;
  transition: all 0.2s;
}

.fruit-card.labeled-sweet {
  border-color: #22c55e;
  background: #f0fdf4;
}

.fruit-card.labeled-sour {
  border-color: #eab308;
  background: #fefce8;
}

.fruit-card.disabled {
  opacity: 0.8;
}

.fruit-emoji {
  font-size: 3rem;
  margin-bottom: 0.5rem;
}

.fruit-name {
  font-weight: 600;
  color: #1f2937;
  margin-bottom: 0.5rem;
}

.fruit-features {
  margin-bottom: 0.75rem;
}

.feature {
  margin-bottom: 0.5rem;
}

.feature-label {
  font-size: 0.7rem;
  color: #6b7280;
  display: block;
  text-align: left;
  margin-bottom: 0.25rem;
}

.feature-bar {
  height: 6px;
  background: #e5e7eb;
  border-radius: 3px;
  overflow: hidden;
}

.feature-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.3s;
}

.feature-fill.sweet {
  background: linear-gradient(90deg, #22c55e, #86efac);
}

.feature-fill.sour {
  background: linear-gradient(90deg, #eab308, #fde047);
}

.label-buttons {
  display: flex;
  gap: 0.5rem;
}

.label-btn {
  flex: 1;
  padding: 0.5rem;
  border: 2px solid #e5e7eb;
  background: white;
  border-radius: 0.5rem;
  cursor: pointer;
  font-size: 0.8rem;
  font-weight: 600;
  transition: all 0.2s;
}

.label-btn.sweet:hover, .label-btn.sweet.selected {
  border-color: #22c55e;
  background: #dcfce7;
  color: #166534;
}

.label-btn.sour:hover, .label-btn.sour.selected {
  border-color: #eab308;
  background: #fef9c3;
  color: #854d0e;
