.prediction-badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  border-radius: 1rem;
  font-size: 0.75rem;
  font-weight: 600;
}

.prediction-badge.sweet {
  background: #dcfce7;
  color: #166534;
}

.prediction-badge.sour {
  background: #fef9c3;
  color: #854d0e;
}

