.actual-label {
  font-size: 0.8rem;
  color: #6b7280;
}

.insight-box {
  background: rgba(255, 255, 255, 0.95);
  border-radius: 1rem;
  padding: 1.5rem;
}

.insight-box h3 {
  color: #1f2937;
  font-size: 1rem;
  margin-bottom: 0.75rem;
}

.insight-box p {
  color: #4b5563;
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 0.75rem;
}

.insight-box p:last-child {
  margin-bottom: 0;
}

@media (max-width: 600px) {
  .fruit-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .controls {
    flex-direction: column;
    gap: 0.75rem;
  }
}
